CREATE TABLE subjects (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(40), name VARCHAR(180));
CREATE TABLE academic_terms (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100));
CREATE TABLE attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, subject_id BIGINT NOT NULL, term_id BIGINT NOT NULL, session_date DATE NOT NULL, status VARCHAR(12) NOT NULL, note VARCHAR(500), recorded_by BIGINT NOT NULL);
CREATE TABLE assessments (id BIGINT PRIMARY KEY AUTO_INCREMENT, subject_id BIGINT NOT NULL, term_id BIGINT NOT NULL, title VARCHAR(180), assessment_type VARCHAR(20), max_marks DECIMAL(7,2));
CREATE TABLE assessment_results (id BIGINT PRIMARY KEY AUTO_INCREMENT, assessment_id BIGINT NOT NULL, student_id BIGINT NOT NULL, marks DECIMAL(7,2) NOT NULL);
CREATE TABLE skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, category VARCHAR(80));
CREATE TABLE student_skills (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, skill_id BIGINT NOT NULL, score DECIMAL(5,2) NOT NULL);
CREATE TABLE learning_goals (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, topic VARCHAR(180), progress DECIMAL(5,2) NOT NULL);
CREATE TABLE projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, name VARCHAR(180));
CREATE TABLE activities (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, name VARCHAR(180));
CREATE TABLE certifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, student_id BIGINT NOT NULL, name VARCHAR(180));
